$id = (int)($_GET['id'] ?? 0);
$stmt = $pdo->prepare("SELECT p.*, u.full_name, u.username, s.student_no, s.class_level, fc.name AS category, verifier.full_name AS verifier_name FROM payments p JOIN students s ON s.id = p.student_id JOIN users u ON u.id = s.user_id JOIN fee_categories fc ON fc.id = p.fee_category_id LEFT JOIN users verifier ON verifier.id = p.verified_by WHERE p.id = ?");
$stmt->execute([$id]);
$payment = $stmt->fetch();
