$pageTitle = 'Kwitansi Transaksi';
function angkaTerbilang(int $angka): string
{
    $kata = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];
    if ($angka < 12) return $kata[$angka];
    if ($angka < 20) return angkaTerbilang($angka - 10) . ' belas';
    if ($angka < 100) return angkaTerbilang(intdiv($angka, 10)) . ' puluh ' . angkaTerbilang($angka % 10);
    if ($angka < 200) return 'seratus ' . angkaTerbilang($angka - 100);
    if ($angka < 1000) return angkaTerbilang(intdiv($angka, 100)) . ' ratus ' . angkaTerbilang($angka % 100);
    if ($angka < 2000) return 'seribu ' . angkaTerbilang($angka - 1000);
    if ($angka < 1000000) return angkaTerbilang(intdiv($angka, 1000)) . ' ribu ' . angkaTerbilang($angka % 1000);
    if ($angka < 1000000000) return angkaTerbilang(intdiv($angka, 1000000)) . ' juta ' . angkaTerbilang($angka % 1000000);
    if ($angka < 1000000000000) return angkaTerbilang(intdiv($angka, 1000000000)) . ' miliar ' . angkaTerbilang($angka % 1000000000);
    return (string)$angka;
}
